  'admin_has_rejected_your_withdraw_request  because dsgfdgvdfg' => 'অ্যাডমিন আপনার প্রত্যাহারের অনুরোধ প্রত্যাখ্যান করেছে কারণ dsgfdgvdfg',
  'admin_has_settled_your_withdraw_request' => 'অ্যাডমিন আপনার প্রত্যাহারের অনুরোধ নিষ্পত্তি করেছে',
  'When creating a level  need to prioritize defining the targets before the customer uses this level and points required for a customer to achieve that level. If there is a mismatch in setting these criteria  it may affect the customer s ability to reach the level.' => 'একটি স্তর তৈরি করার সময় গ্রাহক এই স্তরটি ব্যবহার করার আগে লক্ষ্যগুলি সংজ্ঞায়িত করতে অগ্রাধিকার দিতে হবে এবং সেই স্তরটি অর্জনের জন্য গ্রাহকের জন্য প্রয়োজনীয় পয়েন্টগুলি। যদি এই মানদণ্ডগুলি সেট করার ক্ষেত্রে কোনও অমিল থাকে তবে এটি গ্রাহকের স্তরে পৌঁছানোর ক্ষমতাকে প্রভাবিত করতে পারে।',
  'What’s priority & how it effects' => 'অগ্রাধিকার কি এবং এটি কিভাবে প্রভাব ফেলে',
  'Using  Add New Level  the admin can create a new level for customers. To set up a new level  the admin needs to define targets and points to be earned. When a customer meets those targets and earns the required points  they will upgrade to the new level from their current one.' => 'অ্যাড নিউ লেভেল ব্যবহার করে অ্যাডমিন গ্রাহকদের জন্য একটি নতুন স্তর তৈরি করতে পারে। একটি নতুন স্তর সেট আপ করতে প্রশাসককে লক্ষ্য এবং পয়েন্টগুলি অর্জিত করতে হবে। যখন একজন গ্রাহক সেই লক্ষ্যগুলি পূরণ করে এবং প্রয়োজনীয় পয়েন্ট অর্জন করে তখন তারা তাদের বর্তমান থেকে নতুন স্তরে আপগ্রেড করবে।',
  'How to setup level' => 'কিভাবে লেভেল সেটআপ করবেন',
  'When a new customer logs into the app  they start at a default level. This level helps new customers get used to the platform. As the customer completes rides and meets specific performance goals set by the admin  they can move up to the next level.' => 'যখন একটি নতুন গ্রাহক অ্যাপে লগ ইন করে তখন তারা একটি ডিফল্ট স্তরে শুরু করে। এই স্তরটি নতুন গ্রাহকদের প্ল্যাটফর্মে অভ্যস্ত হতে সাহায্য করে। গ্রাহক যখন রাইড সম্পূর্ণ করে এবং প্রশাসকের দ্বারা নির্ধারিত নির্দিষ্ট কর্মক্ষমতা লক্ষ্য পূরণ করে তখন তারা পরবর্তী স্তরে যেতে পারে।',
