  'Want to disable Firebase OTP Verification ' => 'Firebase OTP যাচাইকরণ নিষ্ক্রিয় করতে চান৷ ',
  'With Firebase OTP enabled  verification codes will be sent through Firebase.' => 'Firebase ওটিপি সক্ষম হলে যাচাইকরণ কোডগুলি Firebase-এর মাধ্যমে পাঠানো হবে।',
  'Enable Firebase OTP means users will not receive verification codes through Email or SMS Although those methods are activated.' => 'Firebase OTP সক্ষম করুন মানে ব্যবহারকারীরা ইমেল বা SMS এর মাধ্যমে যাচাইকরণ কোড পাবেন না যদিও এই পদ্ধতিগুলি সক্রিয় করা হয়েছে৷',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'আপনি যদি Firebase OTP অক্ষম করেন ব্যবহারকারীরা আর Firebase এর মাধ্যমে যাচাইকরণ কোড পাবেন না। বিকল্প হিসাবে আপনাকে অবশ্যই ইমেল বা এসএমএস যাচাইকরণ সক্রিয় করতে হবে',
  'For configuring OTP in the Firebase  you must create a Firebase project first.' => 'Firebase-এ OTP কনফিগার করার জন্য আপনাকে প্রথমে একটি Firebase প্রকল্প তৈরি করতে হবে।',
  'Note: Enable Firebase OTP means users will not receive verification codes through Email or SMS although those methods are activated.' => 'দ্রষ্টব্য: Firebase OTP সক্ষম করুন মানে ব্যবহারকারীরা ইমেল বা SMS এর মাধ্যমে যাচাইকরণ কোড পাবেন না যদিও এই পদ্ধতিগুলি সক্রিয় করা হয়েছে।',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative.' => 'আপনি যদি Firebase OTP অক্ষম করেন ব্যবহারকারীরা আর Firebase এর মাধ্যমে যাচাইকরণ কোড পাবেন না। বিকল্প হিসাবে আপনাকে অবশ্যই ইমেল বা এসএমএস যাচাইকরণ সক্রিয় করতে হবে।',
  'For configuring OTP in the Firebase  you must create a Firebase project first. If you haven’t created any project for your application yet  please create a project first.' => 'Firebase-এ OTP কনফিগার করার জন্য আপনাকে প্রথমে একটি Firebase প্রকল্প তৈরি করতে হবে। আপনি যদি আপনার অ্যাপ্লিকেশনের জন্য এখনও কোনও প্রকল্প তৈরি না করে থাকেন তবে অনুগ্রহ করে প্রথমে একটি প্রকল্প তৈরি করুন।',
  'Now go to the' => 'এখন যান',
  'Get started with the project and go to the Sign-in method tab.' => 'প্রকল্পের সাথে শুরু করুন এবং সাইন-ইন পদ্ধতি ট্যাবে যান৷',
  'Ensure to enable the Phone method and press save.' => 'ফোন পদ্ধতি সক্রিয় করা নিশ্চিত করুন এবং সংরক্ষণ টিপুন।',
  'In Message field you can’t change the Customer Name  Parcel ID & Tracking Link. They will automatically generate. You can only edit other text.' => 'বার্তা ক্ষেত্রে আপনি গ্রাহকের নাম পার্সেল আইডি এবং ট্র্যাকিং লিঙ্ক পরিবর্তন করতে পারবেন না। তারা স্বয়ংক্রিয়ভাবে উৎপন্ন হবে. আপনি শুধুমাত্র অন্য পাঠ্য সম্পাদনা করতে পারেন.',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate SMS verification as an alternative.' => 'আপনি যদি Firebase OTP অক্ষম করেন ব্যবহারকারীরা আর Firebase এর মাধ্যমে যাচাইকরণ কোড পাবেন না। বিকল্প হিসেবে আপনাকে অবশ্যই SMS যাচাইকরণ সক্রিয় করতে হবে।',
  'Note: Enable Firebase OTP means users will not receive verification codes through SMS although those methods are activated.' => 'দ্রষ্টব্য: Firebase OTP সক্ষম করুন মানে ব্যবহারকারীরা এসএমএসের মাধ্যমে যাচাইকরণ কোড পাবেন না যদিও সেই পদ্ধতিগুলি সক্রিয় করা হয়েছে।',
  'Firebase OTP Setup' => 'ফায়ারবেস ওটিপি সেটআপ',
  'They will automatically generate. You can only edit other text.' => 'তারা স্বয়ংক্রিয়ভাবে উৎপন্ন হবে. আপনি শুধুমাত্র অন্য পাঠ্য সম্পাদনা করতে পারেন.',
