  'Yes, Approve' => 'হ্যাঁ, অনুমোদন করুন',
  'It looks like your SMS configuration is not set up yet. To enable the OTP system, please set up the SMS configuration first.' => 'মনে হচ্ছে আপনার এসএমএস কনফিগারেশন এখনও সেট আপ করা হয়নি। OTP সিস্টেম সক্ষম করতে, অনুগ্রহ করে প্রথমে এসএমএস কনফিগারেশন সেট আপ করুন৷',
  'Driver level feature is currently turned off from business settings. If you want to active all the level for drivers in the app, turn on the feature from the settings' => 'ড্রাইভার স্তর বৈশিষ্ট্য বর্তমানে ব্যবসা সেটিংস থেকে বন্ধ আছে. আপনি যদি অ্যাপটিতে ড্রাইভারদের জন্য সমস্ত স্তর সক্রিয় করতে চান তবে সেটিংস থেকে বৈশিষ্ট্যটি চালু করুন',
  'Customer level feature is currently turned off from business settings. If you want to active all the level for customers in the app, turn on the feature from the settings' => 'গ্রাহক স্তর বৈশিষ্ট্য বর্তমানে ব্যবসা সেটিংস থেকে বন্ধ আছে. আপনি যদি অ্যাপে গ্রাহকদের জন্য সমস্ত স্তর সক্রিয় করতে চান তবে সেটিংস থেকে বৈশিষ্ট্যটি চালু করুন',
  'Okay, Got It' => 'ঠিক আছে, বুঝেছি',
