  'JPG, JPEG, PNG,Gif Image size : Max 2 MB' => 'JPG, JPEG, PNG, Gif ছবির আকার: সর্বোচ্চ 2 MB',
  'If you deactivate this level, all driver under this level will not be able to see the level details in their profile.' => 'আপনি যদি এই স্তরটি নিষ্ক্রিয় করেন, তবে এই স্তরের অধীনে সমস্ত ড্রাইভার তাদের প্রোফাইলে স্তরের বিবরণ দেখতে সক্ষম হবে না।',
  'Sorry you can t delete this driver, because there are ongoing rides or payment due this driver. ' => 'দুঃখিত আপনি এই ড্রাইভারটি মুছতে পারবেন না, কারণ এই ড্রাইভারের বকেয়া চলমান রাইড বা পেমেন্ট রয়েছে। ',
  'If you deactivate this level, all customer under this level will not be able to see the level details in their profile.' => 'আপনি যদি এই স্তরটি নিষ্ক্রিয় করেন তবে এই স্তরের অধীনে সমস্ত গ্রাহক তাদের প্রোফাইলে স্তরের বিবরণ দেখতে সক্ষম হবেন না।',
  'Sorry you can t delete this customer, because there are ongoing rides or payment due this customer. ' => 'দুঃখিত আপনি এই গ্রাহককে মুছতে পারবেন না, কারণ এই গ্রাহকের বকেয়া রাইড বা অর্থপ্রদান চলছে। ',
  'When toggle is ON, the fare is set by category  when OFF, it s the same for all.' => 'যখন টগল চালু থাকে, বন্ধ থাকা অবস্থায় ভাড়াটি বিভাগ অনুসারে সেট করা হয়, এটি সবার জন্য একই।',
  'GIF, Jason Less Than 1MB' => 'GIF, জেসন 1MB এর কম',
  'If it is enabled, the driver must verify their identity based on periodic time setup. Setup will appear when you select this option' => 'এটি সক্রিয় থাকলে, ড্রাইভারকে পর্যায়ক্রমিক সময় সেটআপের উপর ভিত্তি করে তাদের পরিচয় যাচাই করতে হবে। আপনি এই বিকল্পটি নির্বাচন করলে সেটআপ প্রদর্শিত হবে',
  'if_you_want_to_charge_more_for_scheduled_trips_than_regular_trips,_turn_on_the_switch.' => 'আপনি যদি নিয়মিত ভ্রমণের চেয়ে নির্ধারিত ট্রিপের জন্য বেশি চার্জ করতে চান, তাহলে সুইচটি চালু করুন।',
  'if_the_user_fails_to_get_the_OTP_within_a_certain_time,_user_can_request_a_resend' => 'ব্যবহারকারী একটি নির্দিষ্ট সময়ের মধ্যে OTP পেতে ব্যর্থ হলে, ব্যবহারকারী পুনরায় পাঠানোর অনুরোধ করতে পারেন',
  'If the toggle is turned ON, Customer will notify if their requested weight exceeds the capacity.' => 'টগল চালু থাকলে, গ্রাহক তাদের অনুরোধকৃত ওজন ধারণক্ষমতার বেশি হলে তা অবহিত করবে।',
  'Set the value of the day, after that day is over can’t get the referral discount.' => 'দিনের মান নির্ধারণ করুন, সেই দিন শেষ হওয়ার পরে রেফারেল ছাড় পাওয়া যাবে না।',
  'If the toggle is turned ON, customers or drivers will see a list of reasons when sending a safety alert.' => 'যদি টগল চালু করা হয়, গ্রাহক বা ড্রাইভার নিরাপত্তা সতর্কতা পাঠানোর সময় কারণগুলির একটি তালিকা দেখতে পাবেন।',
  ', the support section will no longer see this Topic & Answer.' => ', সমর্থন বিভাগ আর এই বিষয় এবং উত্তর দেখতে পাবে না।',
  'If toggle ON, after complete a trip within a certain time Customer and Drive can use safety feature' => 'টগল চালু হলে, নির্দিষ্ট সময়ের মধ্যে একটি ট্রিপ সম্পূর্ণ করার পর গ্রাহক এবং ড্রাইভ নিরাপত্তা বৈশিষ্ট্য ব্যবহার করতে পারবেন',
  'Note: Please make sure to use the obtained information securely and in accordance with Firebase and FCM documentation, terms of service, and any applicable laws and regulations.' => 'দ্রষ্টব্য: অনুগ্রহ করে নিশ্চিত করুন যে প্রাপ্ত তথ্য নিরাপদে এবং Firebase এবং FCM ডকুমেন্টেশন, পরিষেবার শর্তাবলী এবং যেকোনো প্রযোজ্য আইন ও প্রবিধান অনুযায়ী ব্যবহার করা হয়েছে।',
  'JPG, JPEG, PNG, WEBP Less Than 1MB' => 'JPG, JPEG, PNG, WEBP 1MB এর চেয়ে কম',
  'The value of Customer payment successful must contain the placeholders: {paidAmount}, {methodName}.' => 'সফল গ্রাহক অর্থপ্রদানের মানটিতে অবশ্যই স্থানধারক থাকতে হবে: :paidAmount, :methodName।',
  'JPG, JPEG, PNG, WEBP. Less Than 1MB' => 'JPG, JPEG, PNG, WEBP। 1MB এর কম',
  'Set minimum iOS app version. If user don t have, they ll be requested a force update.' => 'সর্বনিম্ন iOS অ্যাপ সংস্করণ সেট করুন। ব্যবহারকারীর কাছে না থাকলে, তাদের একটি ফোর্স আপডেটের জন্য অনুরোধ করা হবে।',
