  'When active, the surge fee is automatically added to the normal fare for rides or parcel deliveries.' => 'সক্রিয় হলে, রাইড বা পার্সেল ডেলিভারির জন্য স্বাভাবিক ভাড়ার সাথে সার্জ ফি স্বয়ংক্রিয়ভাবে যোগ হয়ে যায়।',
  'The admin manually creates a surge price rule for specific zones, vehicle types, or time periods.' => 'প্রশাসক ম্যানুয়ালি নির্দিষ্ট জোন, গাড়ির ধরন বা সময়কালের জন্য একটি বাড়তি দামের নিয়ম তৈরি করেন।',
