  'Surge Price is an extra fee added to rides or parcel deliveries during high-demand or difficult times when completing a trip requires more effort from drivers' => 'উচ্চ-চাহিদা বা কঠিন সময়ে রাইড বা পার্সেল ডেলিভারিতে যোগ করা অতিরিক্ত ফি হল ট্রিপ সম্পূর্ণ করার জন্য ড্রাইভারদের থেকে আরও বেশি পরিশ্রমের প্রয়োজন।',
