  'Wallet_bonus' => 'ওয়ালেট বোনাস',
  'if_enabled,_drivers_can_register_themselves_from_the_driver_app' => 'সক্ষম হলে, ড্রাইভাররা ড্রাইভার অ্যাপ থেকে নিজেদের নিবন্ধন করতে পারে',
  'Set the maximum number of parcels delivery a driver can carry at once. Once the limit is reached, the driver cannot accept new parcel requests until existing deliveries are completed.' => 'একজন ড্রাইভার একবারে সর্বোচ্চ কতগুলি পার্সেল ডেলিভারি বহন করতে পারে তা সেট করুন। একবার সীমা পৌঁছে গেলে, বিদ্যমান ডেলিভারি সম্পূর্ণ না হওয়া পর্যন্ত ড্রাইভার নতুন পার্সেল অনুরোধ গ্রহণ করতে পারবে না।',
  'Enable this, customers will gain access to level-specific features and benefits' => 'এটি সক্ষম করুন, গ্রাহকরা স্তর-নির্দিষ্ট বৈশিষ্ট্য এবং সুবিধাগুলিতে অ্যাক্সেস পাবেন৷',
  'If a driver updates the details of an existing vehicle, certain changes may require admin approval.' => 'যদি একজন ড্রাইভার একটি বিদ্যমান গাড়ির বিবরণ আপডেট করে, তবে কিছু পরিবর্তনের জন্য প্রশাসকের অনুমোদনের প্রয়োজন হতে পারে।',
  'Ex: 100' => 'যেমন: 100',
  'Bonus_List' => 'বোনাস তালিকা',
  'Driver Cash in Hand Setup' => 'ড্রাইভার ক্যাশ ইন হ্যান্ড সেটআপ',
  'Manage the Cash in Hand balance of Deliveryman from here' => 'এখান থেকে ডেলিভারিম্যানের ক্যাশ ইন হ্যান্ড ব্যালেন্স ম্যানেজ করুন',
  'SUBMIT' => 'জমা দিন',
  'add_nesdfdsfw_model' => 'nesdfdsfw মডেল যোগ করুন',
  'add_New_Vsdfdsfehicle' => 'নতুন Vsdfdsfehicle যোগ করুন',
  'edit_vehisdfdscle' => 'Vehisdfdscle সম্পাদনা করুন',
  'available_vehicsdfdsfles_in_this_zone' => 'এই জোনে যানবাহন পাওয়া যায়',
  'business_managsdfdsfement' => 'ব্যবসায়িক ব্যবস্থাপনা',
  'If Yes, customers can add routes between pickup and destination' => 'যদি হ্যাঁ, গ্রাহকরা পিকআপ এবং গন্তব্যের মধ্যে রুট যোগ করতে পারেন',
  'When the time is over, the requests get removed automatically.' => 'সময় শেষ হয়ে গেলে, অনুরোধগুলি স্বয়ংক্রিয়ভাবে সরানো হয়।',
  'When this option is enabled, for starting the trip, the driver will need to get an OTP from the customer' => 'এই বিকল্পটি চালু থাকলে, ট্রিপ শুরু করার জন্য, ড্রাইভারকে গ্রাহকের কাছ থেকে একটি OTP পেতে হবে',
  'Do you want to turn ON Parcel Return Time & Fee for driver  When it’s ON, the driver need to pay parcel return delay fee. ' => 'আপনি কি চালকের জন্য পার্সেল রিটার্নের সময় এবং ফি চালু করতে চান যখন এটি চালু থাকে, ড্রাইভারকে পার্সেল ফেরত বিলম্বের ফি দিতে হবে। ',
  'this_time_is_the_minimum_advance_booking_time_for_scheduled_trips,_customer_cant_book_a_scheduled_trip_before_this.' => 'এই সময়টি নির্ধারিত ভ্রমণের জন্য সর্বনিম্ন অগ্রিম বুকিং সময়, গ্রাহক এর আগে একটি নির্ধারিত ট্রিপ বুক করতে পারবেন না।',
  'this_time_is_the_maximum_advance_booking_time_for_scheduled_trips,_customer_can_not_book_a_scheduled_trip_if_the_time_is_over.' => 'এই সময়টি নির্ধারিত ট্রিপের জন্য সর্বোচ্চ অগ্রিম বুকিং সময়, সময় শেষ হলে গ্রাহক একটি নির্ধারিত ট্রিপ বুক করতে পারবেন না।',
  'By default, it is set to 5 kilometers' => 'ডিফল্টরূপে, এটি 5 কিলোমিটারে সেট করা আছে',
  'By default, it is set to 10 meters' => 'ডিফল্টরূপে, এটি 10 মিটার সেট করা হয়',
  'Socket connection establishing URL is base url, Its is not editable' => 'সকেট সংযোগ স্থাপন করা URL হল বেস ইউআরএল, এটি সম্পাদনাযোগ্য নয়',
  'Do you want to turn ON Parcel Tracking Link for customer  When turned ON, customers will receive a tracking link once the parcel is confirmed.' => 'আপনি কি গ্রাহকের জন্য পার্সেল ট্র্যাকিং লিঙ্ক চালু করতে চান যখন চালু থাকে, পার্সেল নিশ্চিত হয়ে গেলে গ্রাহকরা একটি ট্র্যাকিং লিঙ্ক পাবেন।',
  'Hear you can write a massage body. Customer Name, Parcel ID & Tracking link will generate automatically for each individual parcel.' => 'আপনি একটি ম্যাসেজ শরীর লিখতে পারেন শুনুন. গ্রাহকের নাম, পার্সেল আইডি এবং ট্র্যাকিং লিঙ্ক প্রতিটি পৃথক পার্সেলের জন্য স্বয়ংক্রিয়ভাবে তৈরি হবে।',
  'When the toggle is turned ON, the parcel return time and fee are activated  when turned OFF, they are deactivated.' => 'যখন টগল চালু করা হয়, পার্সেল ফেরত সময় এবং ফি সক্রিয় করা হয় যখন বন্ধ করা হয়, সেগুলি নিষ্ক্রিয় করা হয়।',
  'If turned ON, customer will notify if their requested weight exceeds the capacity.' => 'চালু থাকলে, গ্রাহক তাদের অনুরোধকৃত ওজন ধারণক্ষমতার চেয়ে বেশি হলে তা জানিয়ে দেবে।',
  'If the toggle is turned OFF, Customer will not notify if their requested weight exceeds the capacity.' => 'টগল বন্ধ করা থাকলে, গ্রাহক তাদের অনুরোধকৃত ওজন ধারণক্ষমতার চেয়ে বেশি হলে তা অবহিত করবে না।',
  'Image format : jpg, png, jpeg, webp | Maximum size : 5MB' => 'চিত্র বিন্যাস: jpg, png, jpeg, webp | সর্বোচ্চ আকার: 5MB',
  'Navigate Life with Ease: Welcome to DriveMond, Your Premier Ride-Sharing Experience!' => 'সহজে জীবন নেভিগেট করুন: ড্রাইভমন্ডে স্বাগতম, আপনার প্রিমিয়ার রাইড-শেয়ারিং অভিজ্ঞতা!',
  'Unlock a World of Convenience: Welcome to DriveMond, Your Ultimate Ride-Sharing Destination! Seamlessly Connect with Reliable Drivers, Enjoy Comfortable Journeys- One Ride at a Time.' => 'সুবিধার একটি বিশ্ব আনলক করুন: ড্রাইভমন্ডে স্বাগতম, আপনার চূড়ান্ত রাইড-শেয়ারিং গন্তব্য! নির্বিঘ্নে নির্ভরযোগ্য ড্রাইভারদের সাথে সংযোগ করুন, আরামদায়ক যাত্রা উপভোগ করুন- একবারে একটি রাইড।',
  ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ' => ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ',
  ' Join our community of happy customers! Discover seamless experiences, personalized service, and satisfaction guaranteed. Your joy is our priority! ' => ' খুশি গ্রাহকদের আমাদের সম্প্রদায়ে যোগদান করুন! নির্বিঘ্ন অভিজ্ঞতা আবিষ্কার করুন, ব্যক্তিগতকৃত পরিষেবা, এবং সন্তুষ্টি গ্যারান্টিযুক্ত। আপনার আনন্দ আমাদের অগ্রাধিকার! ',
  'Set minimum Android app version. If user don t have, they ll be requested a force update.' => 'ন্যূনতম Android অ্যাপ সংস্করণ সেট করুন। ব্যবহারকারীর কাছে না থাকলে, তাদের একটি ফোর্স আপডেটের জন্য অনুরোধ করা হবে।',
  'File Format - jpg, jpeg, png, webp | Image Size - Maximum Size 5 MB.' => 'ফাইল ফরম্যাট - jpg, jpeg, png, webp | ছবির সাইজ - সর্বোচ্চ সাইজ ৫ এমবি।',
  'With Firebase OTP enabled, verification codes will be sent through Firebase.' => 'Firebase OTP সক্ষম হলে, যাচাইকরণ কোডগুলি Firebase-এর মাধ্যমে পাঠানো হবে।',
  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'আপনি Firebase OTP অক্ষম করলে, ব্যবহারকারীরা Firebase এর মাধ্যমে আর যাচাইকরণ কোড পাবেন না। বিকল্প হিসাবে আপনাকে অবশ্যই ইমেল বা এসএমএস যাচাইকরণ সক্রিয় করতে হবে',
  'For configuring OTP in the Firebase, you must create a Firebase project first. If you haven’t created any project for your application yet, please create a project first.' => 'Firebase-এ OTP কনফিগার করার জন্য, আপনাকে প্রথমে একটি Firebase প্রকল্প তৈরি করতে হবে। আপনি যদি এখনও আপনার অ্যাপ্লিকেশনের জন্য কোনো প্রকল্প তৈরি না করে থাকেন, তাহলে অনুগ্রহ করে প্রথমে একটি প্রকল্প তৈরি করুন।',
  'From the Sign-in providers section, select the Phone option.' => 'সাইন-ইন প্রদানকারী বিভাগ থেকে, ফোন বিকল্পটি নির্বাচন করুন।',
  'If there is any existing user in this level, you can not change the status' => 'এই স্তরে বিদ্যমান কোনো ব্যবহারকারী থাকলে, আপনি স্থিতি পরিবর্তন করতে পারবেন না',
  'Setting the Stage for Rewards and Targets. Once a target is completed or fulfilled, move on to the next one' => 'পুরষ্কার এবং লক্ষ্যগুলির জন্য পর্যায় সেট করা। একবার একটি টার্গেট সম্পূর্ণ বা পূর্ণ হয়ে গেলে, পরবর্তীতে যান',
  'When a new customer logs into the app, they start at a default level. This level helps new customers get used to the platform. As the customer completes rides and meets specific performance goals set by the admin, they can move up to the next level.' => 'যখন একটি নতুন গ্রাহক অ্যাপে লগ ইন করেন, তখন তারা একটি ডিফল্ট স্তরে শুরু করে। এই স্তরটি নতুন গ্রাহকদের প্ল্যাটফর্মে অভ্যস্ত হতে সাহায্য করে। গ্রাহক যেহেতু রাইড সম্পূর্ণ করে এবং প্রশাসকের দ্বারা নির্ধারিত নির্দিষ্ট কর্মক্ষমতা লক্ষ্য পূরণ করে, তারা পরবর্তী স্তরে যেতে পারে।',
  'Using  Add New Level  the admin can create a new level for customers. To set up a new level, the admin needs to define targets and points to be earned. When a customer meets those targets and earns the required points, they will upgrade to the new level from their current one.' => 'অ্যাড নিউ লেভেল ব্যবহার করে অ্যাডমিন গ্রাহকদের জন্য একটি নতুন স্তর তৈরি করতে পারে। একটি নতুন স্তর সেট আপ করার জন্য, প্রশাসককে লক্ষ্য এবং পয়েন্টগুলি অর্জিত করতে হবে। যখন একজন গ্রাহক সেই লক্ষ্যগুলি পূরণ করে এবং প্রয়োজনীয় পয়েন্ট অর্জন করে, তখন তারা তাদের বর্তমান থেকে নতুন স্তরে আপগ্রেড করবে।',
  'When creating a level, need to prioritize defining the targets before the customer uses this level and points required for a customer to achieve that level. If there is a mismatch in setting these criteria, it may affect the customer s ability to reach the level.' => 'একটি স্তর তৈরি করার সময়, গ্রাহক এই স্তরটি ব্যবহার করার আগে লক্ষ্যগুলি সংজ্ঞায়িত করতে অগ্রাধিকার দিতে হবে এবং সেই স্তরটি অর্জনের জন্য গ্রাহকের জন্য প্রয়োজনীয় পয়েন্টগুলি। যদি এই মানদণ্ডগুলি সেট করার ক্ষেত্রে কোনও অমিল থাকে তবে এটি গ্রাহকের স্তরে পৌঁছানোর ক্ষমতাকে প্রভাবিত করতে পারে।',
  'At present, there is only one level available, which is the default level. When a customer logs in to the app for the first time, they will automatically be assigned the default level.' => 'বর্তমানে, শুধুমাত্র একটি স্তর উপলব্ধ, যা ডিফল্ট স্তর। যখন কোনও গ্রাহক প্রথমবার অ্যাপটিতে লগ ইন করেন, তখন তাদের স্বয়ংক্রিয়ভাবে ডিফল্ট স্তর বরাদ্দ করা হবে।',
  'At present, there is only one level available, which is the default level. When a driver logs in to the app for the first time, they will automatically be assigned the default level.' => 'বর্তমানে, শুধুমাত্র একটি স্তর উপলব্ধ, যা ডিফল্ট স্তর। যখন কোনও ড্রাইভার প্রথমবার অ্যাপে লগ ইন করে, তখন তাদের স্বয়ংক্রিয়ভাবে ডিফল্ট স্তর বরাদ্দ করা হবে।',
  'Coupon already expired, You do not change this status.' => 'কুপন ইতিমধ্যে মেয়াদ শেষ, আপনি এই অবস্থা পরিবর্তন করবেন না.',
  'Once you turn off this option, Customers will not be required to pay any Extra Fares in this Zone' => 'একবার আপনি এই বিকল্পটি বন্ধ করে দিলে, গ্রাহকদের এই অঞ্চলে কোনো অতিরিক্ত ভাড়া দিতে হবে না',
  'File Format - jpg, png, jpeg, webp' => 'ফাইল ফরম্যাট - jpg, png, jpeg, webp',
  'wallet_bonus' => 'ওয়ালেট বোনাস',
  'Wallet Bonus' => 'ওয়ালেট বোনাস',
  'bonus_title' => 'বোনাস শিরোনাম',
  'write_the_bonus_title_within_50_characters.' => '50 অক্ষরের মধ্যে বোনাস শিরোনাম লিখুন।',
  'Ex: Eid Dhamaka' => 'যেমন: ঈদ ধামাকা',
  '0/50' => '0/50',
  'write_the_short_description_title_within_256_characters' => '256 অক্ষরের মধ্যে সংক্ষিপ্ত বিবরণ শিরোনাম লিখুন',
  '0/256' => '0/256',
  'bonus_amount' => 'বোনাস পরিমাণ',
