  'Want to enable referral earnings' => 'রেফারেল উপার্জন সক্ষম করতে চান',
  'If you enable referral earnings, customers will be able to earn rewards by referring new users.' => 'আপনি রেফারেল উপার্জন সক্ষম করলে, গ্রাহকরা নতুন ব্যবহারকারীদের উল্লেখ করে পুরষ্কার অর্জন করতে সক্ষম হবেন।',
  'If you disable referral earnings, drivers will no longer receive rewards for referring new users' => 'আপনি রেফারেল উপার্জন অক্ষম করলে, ড্রাইভাররা নতুন ব্যবহারকারীদের রেফার করার জন্য আর পুরস্কার পাবেন না',
  'If you enable referral earnings, drivers will be able to earn rewards by referring new users.' => 'আপনি রেফারেল উপার্জন সক্ষম করলে, ড্রাইভাররা নতুন ব্যবহারকারীদের রেফার করে পুরস্কার অর্জন করতে সক্ষম হবে।',
  'The idle fee is applied when the driver pauses an ongoing trip.' => 'নিষ্ক্রিয় ফি প্রযোজ্য হয় যখন ড্রাইভার একটি চলমান ট্রিপে বিরতি দেয়।',
  'Set the default currency used across your platform for pricing and transactions.' => 'মূল্য নির্ধারণ এবং লেনদেনের জন্য আপনার প্ল্যাটফর্ম জুড়ে ব্যবহৃত ডিফল্ট মুদ্রা সেট করুন।',
  'Want to enable driver self-registration' => 'ড্রাইভার স্ব-নিবন্ধন সক্ষম করতে চান',
  ' If you turn on the driver self-registration, drivers can register directly. This streamlines onboarding.' => ' আপনি ড্রাইভার স্ব-নিবন্ধন চালু করলে, ড্রাইভার সরাসরি নিবন্ধন করতে পারে। এই অনবোর্ডিং streamlines.',
