  'If you turn off the driver self-registration, drivers will require an internal administrator to register their accounts.' => 'আপনি ড্রাইভার স্ব-নিবন্ধন বন্ধ করলে, ড্রাইভারদের তাদের অ্যাকাউন্ট নিবন্ধন করার জন্য একজন অভ্যন্তরীণ প্রশাসকের প্রয়োজন হবে।',
