  'The option you select will be used to display maps, routes, and location services in the app and website.' => 'আপনার নির্বাচন করা বিকল্পটি অ্যাপ এবং ওয়েবসাইটে মানচিত্র, রুট এবং অবস্থান পরিষেবাগুলি প্রদর্শন করতে ব্যবহার করা হবে।',
  'Google map aPI setup' => 'গুগল ম্যাপ এপিআই সেটআপ',
  'Set up the api configuration for google map.' => 'গুগল ম্যাপের জন্য এপিআই কনফিগারেশন সেট আপ করুন।',
  'Client key should have enable map javascript api and you can restrict it with http refer . Server key should have enable place api key and you can restrict it with ip . You can use same api for both field without any restrictions.' => 'ক্লায়েন্ট কী মানচিত্র জাভাস্ক্রিপ্ট এপিআই সক্ষম করা উচিত এবং আপনি এটি http উল্লেখের সাথে সীমাবদ্ধ করতে পারেন। সার্ভার কী-তে প্লেস এপিআই কী সক্ষম হওয়া উচিত এবং আপনি এটি ip দিয়ে সীমাবদ্ধ করতে পারেন। আপনি কোন সীমাবদ্ধতা ছাড়াই উভয় ক্ষেত্রের জন্য একই এপিআই ব্যবহার করতে পারেন।',
  'Google Maps' => 'গুগল ম্যাপ',
