  'When enabled, the voice option will appear on the applications chat page.' => 'সক্রিয় করা হলে, ভয়েস বিকল্পটি অ্যাপ্লিকেশন চ্যাট পৃষ্ঠায় প্রদর্শিত হবে।',
  'Do you want to turn OFF voice message support for the applications' => 'আপনি কি অ্যাপ্লিকেশনগুলির জন্য ভয়েস বার্তা সমর্থন বন্ধ করতে চান৷',
  'Do you want to turn ON voice message support for the applications' => 'আপনি কি অ্যাপ্লিকেশনগুলির জন্য ভয়েস বার্তা সমর্থন চালু করতে চান৷',
  'Do you want to turn OFF saved replies for the support center' => 'আপনি কি সমর্থন কেন্দ্রের জন্য সংরক্ষিত উত্তরগুলি বন্ধ করতে চান৷',
  'When it’s off the support center will not be able to see any saved replies.' => 'এটি বন্ধ থাকলে সহায়তা কেন্দ্র কোনো সংরক্ষিত উত্তর দেখতে সক্ষম হবে না।',
  'When it’s on the support center will be able to see saved replies.' => 'এটি সমর্থন কেন্দ্রে থাকলে সংরক্ষিত উত্তরগুলি দেখতে সক্ষম হবে।',
  'Do you want to turn ON saved replies for the support center' => 'আপনি কি সমর্থন কেন্দ্রের জন্য সংরক্ষিত উত্তরগুলি চালু করতে চান৷',
  'Social Media' => 'সোশ্যাল মিডিয়া',
  'Social Media Login' => 'সোশ্যাল মিডিয়া লগইন',
  'Google Login' => 'গুগল লগইন',
  'Apple Login' => 'অ্যাপল লগইন',
  'Facebook Login' => 'ফেসবুক লগইন',
  'Social Media Login Setup' => 'সোশ্যাল মিডিয়া লগইন সেটআপ',
  'Configure Social Media Setup' => 'সোশ্যাল মিডিয়া সেটআপ কনফিগার করুন',
  'You can use following login from Customer Login page after active check Social Media Login.' => 'সক্রিয় চেক সোশ্যাল মিডিয়া লগইন করার পরে আপনি গ্রাহক লগইন পৃষ্ঠা থেকে নিম্নলিখিত লগইন ব্যবহার করতে পারেন।',
  'Use {provider} login as your customer Social Media Login turn the switch & setup the required files.' => 'আপনার গ্রাহক হিসাবে :provider লগইন ব্যবহার করুন সোশ্যাল মিডিয়া লগইন করুন সুইচটি চালু করুন এবং প্রয়োজনীয় ফাইলগুলি সেটআপ করুন৷',
  'Get Credential Setup' => 'শংসাপত্র সেটআপ পান',
  'Store Bundle ID' => 'স্টোর বান্ডিল আইডি',
  'Ex: Bundle ID' => 'যেমন: বান্ডেল আইডি',
  'Store Client Secret Key' => 'স্টোর ক্লায়েন্ট সিক্রেট কী',
  'Ex: Client secret key' => 'যেমন: ক্লায়েন্ট গোপন কী',
  'Google' => 'গুগল',
  'Facebook' => 'ফেসবুক',
  'Apple' => 'আপেল',
  'With Social Media Login, customers can log in using social media accounts.' => 'সোশ্যাল মিডিয়া লগইনের মাধ্যমে গ্রাহকরা সোশ্যাল মিডিয়া অ্যাকাউন্ট ব্যবহার করে লগ ইন করতে পারেন।',
  'Select which social media you want for customer login' => 'গ্রাহক লগইন করার জন্য আপনি কোন সামাজিক মিডিয়া চান তা নির্বাচন করুন',
  'Connect 3rd party login system from here' => 'এখান থেকে থার্ড পার্টি লগইন সিস্টেম কানেক্ট করুন',
  'At least one social media must remain active for login. Otherwise social media login cannot work.' => 'লগইন করার জন্য কমপক্ষে একটি সামাজিক মিডিয়া সক্রিয় থাকতে হবে। অন্যথায় সোশ্যাল মিডিয়া লগইন কাজ করতে পারবে না।',
  '{provider} is currently disabled from configure 3rd party social login options.' => ':provider বর্তমানে কনফিগার 3য় পক্ষের সামাজিক লগইন বিকল্পগুলি থেকে অক্ষম করা হয়েছে৷',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'Google লগইন সক্ষম করে, গ্রাহকরা তাদের বিদ্যমান Gmail শংসাপত্র ব্যবহার করে সাইটে লগ ইন করতে পারেন।',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials.' => 'Facebook লগইন সক্ষম করে, গ্রাহকরা তাদের বিদ্যমান Facebook শংসাপত্র ব্যবহার করে সাইটে লগ ইন করতে পারেন।',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices.' => 'অ্যাপল লগইন সক্ষম করে, গ্রাহকরা তাদের বিদ্যমান অ্যাপল লগইন শংসাপত্র ব্যবহার করে সাইটে লগ ইন করতে পারেন, শুধুমাত্র অ্যাপল ডিভাইসের জন্য।',
  'Google API Setup Instructions' => 'Google API সেটআপ নির্দেশাবলী',
  'Apple API Setup Instructions' => 'অ্যাপল এপিআই সেটআপ নির্দেশাবলী',
  'Sign in to your Apple Developer account and open Certificates, Identifiers & Profiles.' => 'আপনার অ্যাপল ডেভেলপার অ্যাকাউন্টে সাইন ইন করুন এবং সার্টিফিকেট, আইডেন্টিফায়ার এবং প্রোফাইল খুলুন।',
  'Copy your Team ID from the top-right of the Membership page and paste it into the Team id field.' => 'সদস্যতা পৃষ্ঠার উপরের ডানদিকে আপনার টিম আইডি কপি করুন এবং টিম আইডি ক্ষেত্রে পেস্ট করুন।',
  'Open Identifiers, register or select an App ID, and enable the Sign in with Apple capability.' => 'আইডেন্টিফায়ার খুলুন, নিবন্ধন করুন বা একটি অ্যাপ আইডি নির্বাচন করুন এবং অ্যাপল সক্ষমতার সাথে সাইন ইন সক্ষম করুন৷',
  'Copy the Bundle ID of that App ID and paste it into the Store Bundle ID field.' => 'সেই অ্যাপ আইডির বান্ডেল আইডি কপি করুন এবং স্টোর বান্ডেল আইডি ফিল্ডে পেস্ট করুন।',
  'Open Keys, create a new key with Sign in with Apple enabled, and copy its Key ID into the Store Client Secret Key field.' => 'কী খুলুন, অ্যাপল সক্ষম করে সাইন ইন করে একটি নতুন কী তৈরি করুন এবং স্টোর ক্লায়েন্ট সিক্রেট কী ক্ষেত্রে এর কী আইডি কপি করুন।',
  'Download the AuthKey file (.p8), upload it in the Choose updated file field, and store it safely as it can be downloaded only once.' => 'AuthKey ফাইলটি (.p8) ডাউনলোড করুন, এটিকে আপডেট করা ফাইল চয়ন করুন ক্ষেত্রে আপলোড করুন এবং এটিকে নিরাপদে সংরক্ষণ করুন কারণ এটি শুধুমাত্র একবার ডাউনলোড করা যায়৷',
  'Turn on the switch and click Save.' => 'সুইচটি চালু করুন এবং সংরক্ষণ করুন ক্লিক করুন।',
  'The Bundle ID is required when Apple login is active.' => 'অ্যাপল লগইন সক্রিয় থাকলে বান্ডেল আইডি প্রয়োজন।',
  'The Key ID is required when Apple login is active.' => 'অ্যাপল লগইন সক্রিয় থাকাকালীন কী আইডি প্রয়োজন।',
  'The Team ID is required when Apple login is active.' => 'অ্যাপল লগইন সক্রিয় থাকাকালীন টিম আইডি প্রয়োজন।',
  'The AuthKey (.p8) file is required when Apple login is active.' => 'যখন Apple লগইন সক্রিয় থাকে তখন AuthKey (.p8) ফাইলের প্রয়োজন হয়৷',
  'The uploaded file must be a .p8 AuthKey file.' => 'আপলোড করা ফাইলটি একটি .p8 AuthKey ফাইল হতে হবে।',
  'The uploaded file is not a valid AuthKey (.p8) private key file.' => 'আপলোড করা ফাইলটি একটি বৈধ AuthKey (.p8) ব্যক্তিগত কী ফাইল নয়৷',
  'A key file has been uploaded.' => 'একটি কী ফাইল আপলোড করা হয়েছে।',
  'Facebook API Setup Instructions' => 'Facebook API সেটআপ নির্দেশাবলী',
  'Go to the Google Developers Console.' => 'Google Developers Console-এ যান।',
  'Create a new project or select an existing project.' => 'একটি নতুন প্রকল্প তৈরি করুন বা একটি বিদ্যমান প্রকল্প নির্বাচন করুন।',
  'Click on Credentials in the left-hand menu.' => 'বামদিকের মেনুতে শংসাপত্রে ক্লিক করুন।',
  'Create an OAuth client ID for a web application.' => 'একটি ওয়েব অ্যাপ্লিকেশনের জন্য একটি OAuth ক্লায়েন্ট আইডি তৈরি করুন৷',
  'Enter a name for your client ID and click Create.' => 'আপনার ক্লায়েন্ট আইডির জন্য একটি নাম লিখুন এবং তৈরি করুন ক্লিক করুন।',
  'Enter the URL of your website as an authorized JavaScript origin.' => 'একটি অনুমোদিত জাভাস্ক্রিপ্ট উত্স হিসাবে আপনার ওয়েবসাইটের URL লিখুন৷',
  'Enter the callback URL as an authorized redirect URL.' => 'একটি অনুমোদিত পুনঃনির্দেশ URL হিসাবে কলব্যাক URL লিখুন৷',
  'Copy and paste the client ID and client secret into your application settings.' => 'আপনার অ্যাপ্লিকেশন সেটিংসে ক্লায়েন্ট আইডি এবং ক্লায়েন্ট সিক্রেট কপি এবং পেস্ট করুন।',
  'Enable the Google login option in your application settings and thoroughly test the integration before deploying it to a live environment.' => 'আপনার অ্যাপ্লিকেশন সেটিংসে Google লগইন বিকল্পটি সক্ষম করুন এবং একটি লাইভ পরিবেশে এটি স্থাপন করার আগে পুঙ্খানুপুঙ্খভাবে ইন্টিগ্রেশন পরীক্ষা করুন৷',
  'Go to apple developer page' => 'অ্যাপল ডেভেলপার পেজে যান',
  'Click here' => 'এখানে ক্লিক করুন',
  'In the top left corner you can see the Team ID [Apple developer account name] - Team ID.' => 'উপরের বাম কোণে আপনি টিম আইডি [অ্যাপল ডেভেলপার অ্যাকাউন্টের নাম] - টিম আইডি দেখতে পাবেন।',
  'Click plus icon, select App IDs, then click on continue.' => 'প্লাস আইকনে ক্লিক করুন, অ্যাপ আইডি নির্বাচন করুন, তারপর অবিরত ক্লিক করুন।',
  'Put a description and also identifier (identifier that used for app) and this is the Client ID.' => 'একটি বিবরণ রাখুন এবং শনাক্তকারীও (অ্যাপটির জন্য ব্যবহৃত সনাক্তকারী) এবং এটি হল ক্লায়েন্ট আইডি।',
  'Click continue and download the file in device named AuthKey ID.p8 (store it safely and it is used for push notification).' => 'অবিরত ক্লিক করুন এবং AuthKey ID.p8 নামের ডিভাইসে ফাইলটি ডাউনলোড করুন (এটি নিরাপদে সংরক্ষণ করুন এবং এটি পুশ বিজ্ঞপ্তির জন্য ব্যবহৃত হয়)।',
  'Again click plus icon, select Service IDs, then click on continue.' => 'আবার প্লাস আইকনে ক্লিক করুন, সার্ভিস আইডি নির্বাচন করুন, তারপর অবিরত ক্লিক করুন।',
  'Put a description and also identifier and continue.' => 'একটি বিবরণ এবং সনাক্তকারী রাখুন এবং চালিয়ে যান।',
  'Download the file in device named AuthKey KeyID.p8 (this is the service key ID file and also after AuthKey that is the key ID).' => 'AuthKey KeyID.p8 নামের ডিভাইসে ফাইলটি ডাউনলোড করুন (এটি পরিষেবা কী আইডি ফাইল এবং AuthKey এর পরেও এটি কী আইডি)।',
  'Go to the Facebook Developer website.' => 'ফেসবুক ডেভেলপার ওয়েবসাইটে যান।',
  'Create a new app or select an existing app.' => 'একটি নতুন অ্যাপ তৈরি করুন বা একটি বিদ্যমান অ্যাপ নির্বাচন করুন।',
  'Click on Add a New App or select an existing app from the dashboard.' => 'Add a New App এ ক্লিক করুন অথবা ড্যাশবোর্ড থেকে একটি বিদ্যমান অ্যাপ নির্বাচন করুন।',
  'Fill in the required details, such as Display Name, Contact Email, and App Purpose.' => 'প্রয়োজনীয় বিবরণ পূরণ করুন, যেমন ডিসপ্লে নাম, যোগাযোগের ইমেল এবং অ্যাপের উদ্দেশ্য।',
  'Click Create App to create your app.' => 'আপনার অ্যাপ তৈরি করতে অ্যাপ তৈরি করুন ক্লিক করুন।',
  'In the left-hand menu, click on Settings and then Basic to access your app basic settings.' => 'বামদিকের মেনুতে, আপনার অ্যাপের মৌলিক সেটিংস অ্যাক্সেস করতে সেটিংসে এবং তারপর বেসিক-এ ক্লিক করুন।',
  'Scroll down to the Facebook Login section and click on Set Up to configure your Facebook login settings.' => 'Facebook লগইন বিভাগে নিচে স্ক্রোল করুন এবং আপনার Facebook লগইন সেটিংস কনফিগার করতে Set Up এ ক্লিক করুন।',
  'Choose the login behavior, permissions, and other settings as per your requirements.' => 'আপনার প্রয়োজনীয়তা অনুযায়ী লগইন আচরণ, অনুমতি এবং অন্যান্য সেটিংস চয়ন করুন।',
  'Copy and paste the App ID and App Secret into your application settings.' => 'আপনার অ্যাপ্লিকেশন সেটিংসে অ্যাপ আইডি এবং অ্যাপ সিক্রেট কপি এবং পেস্ট করুন।',
  'Enable the Facebook login option in your applications settings and thoroughly test the integration before deploying it to a live environment.' => 'আপনার অ্যাপ্লিকেশন সেটিংসে Facebook লগইন বিকল্পটি সক্ষম করুন এবং একটি লাইভ পরিবেশে এটি স্থাপন করার আগে পুঙ্খানুপুঙ্খভাবে ইন্টিগ্রেশন পরীক্ষা করুন।',
