  'Driver status paused successfully' => 'ড্রাইভার স্ট্যাটাস সফলভাবে পজ করা হয়েছে',
  'Driver status resumed successfully' => 'ড্রাইভারের স্থিতি সফলভাবে পুনরায় শুরু হয়েছে৷',
  'You cannot change the status of a suspended driver' => 'আপনি সাসপেন্ডড ড্রাইভারের অবস্থা পরিবর্তন করতে পারবেন না',
  'day' => 'দিন',
