  'Are you sure want to resume the driver status' => 'আপনি কি ড্রাইভার স্ট্যাটাস পুনরায় শুরু করতে চান?',
  'The driver can go online and receive trip requests again.' => 'ড্রাইভার অনলাইনে যেতে পারে এবং আবার ট্রিপের অনুরোধ পেতে পারে।',
  'Resume' => 'পুনরায় শুরু করুন',
