  'Setup miscellaneous notifications sent to drivers that do not fall under the other categories.' => 'অন্যান্য বিভাগের অধীনে পড়ে না এমন ড্রাইভারদের পাঠানো বিবিধ বিজ্ঞপ্তি সেটআপ করুন।',
