  'Your face verification has failed and your status has been paused. Please verify your identity again to go online.' => 'আপনার মুখ যাচাইকরণ ব্যর্থ হয়েছে এবং আপনার স্ট্যাটাস পজ করা হয়েছে। অনলাইনে যেতে আবার আপনার পরিচয় যাচাই করুন।',
  'Your limit to hold cash in hand has been exceeded. Please pay the due to admin from your wallet page.' => 'আপনার হাতে নগদ রাখার সীমা অতিক্রম করা হয়েছে। আপনার ওয়ালেট পৃষ্ঠা থেকে প্রশাসকের বকেয়া পরিশোধ করুন.',
  'Turn off same time for every day to set a specific day' => 'একটি নির্দিষ্ট দিন সেট করতে প্রতিটি দিনের জন্য একই সময় বন্ধ করুন',
