  'did not match Driver Photo and Vehicle Model' => 'ড্রাইভারের ছবি এবং গাড়ির মডেলের সাথে মেলেনি',
  'trip_canceled_for_driver_identity_mismatch' => 'ড্রাইভার পরিচয় অমিলের জন্য ট্রিপ বাতিল করা হয়েছে',
